def srgb8_to_lin16(u):
    return TO_LIN16[u & 0xFF]


def lin16_to_srgb8(x):
    """binary search: nearest table entry, ties upward — the
    same rule the RTL encode path implements."""
    lo, hi = 0, 255
    while lo < hi:
        mid = (lo + hi + 1) >> 1
        if TO_LIN16[mid] <= x:
            lo = mid
        else:
            hi = mid - 1
    if lo < 255 and TO_LIN16[lo + 1] - x <= x - TO_LIN16[lo]:
        lo += 1
    return lo


def lin12_to_srgb8(u):
    """G2a: 12-bit linear (1/4095) -> 8-bit sRGB via the same
    APU_SRGB_ENC table the rasterizer indexes."""
    return ENC12[u & 0xFFF]
